<section class="page-header"><div><span class="eyebrow">Analytics & exports</span><h1>Reports Centre</h1><p>Sales, client, project, staff and financial reporting from live records.</p></div></section><section class="panel"><form class="filter-bar report-filter" method="get"><label><span>From</span><input type="date" name="from" value="<?= e($from) ?>"></label><label><span>To</span><input type="date" name="to" value="<?= e($to) ?>"></label><label><span>Staff</span><select name="staff_id"><option value="">All staff</option><?php foreach($staffOptions as $option):?><option value="<?= $option['id'] ?>" <?= $filters['staff_id']==$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select></label><label><span>Client</span><select name="client_id"><option value="">All clients</option><?php foreach($clientOptions as $option):?><option value="<?= $option['id'] ?>" <?= $filters['client_id']==$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select></label><label><span>Project</span><select name="project_id"><option value="">All projects</option><?php foreach($projectOptions as $option):?><option value="<?= $option['id'] ?>" <?= $filters['project_id']==$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select></label><label><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach(['Present','Late','Absent','Active','Delayed','Completed','Draft','Sent','Partially Paid','Paid','Overdue','Cancelled','Won','Lost'] as $status):?><option <?= $filters['status']===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach;?></select></label><button class="button button-primary">Apply filters</button><div class="export-menu"><a class="button button-secondary button-sm" href="<?= url('reports/export?'.http_build_query(array_merge(['type'=>'attendance','from'=>$from,'to'=>$to],array_filter($filters)))) ?>">Attendance CSV</a><a class="button button-secondary button-sm" href="<?= url('reports/export?'.http_build_query(array_merge(['type'=>'leads','from'=>$from,'to'=>$to],array_filter($filters)))) ?>">Leads CSV</a><a class="button button-secondary button-sm" href="<?= url('reports/export?'.http_build_query(array_merge(['type'=>'payments','from'=>$from,'to'=>$to],array_filter($filters)))) ?>">Payments CSV</a><a class="button button-secondary button-sm" href="<?= url('reports/export?'.http_build_query(array_merge(['type'=>'payroll','from'=>$from,'to'=>$to],array_filter($filters)))) ?>">Payroll CSV</a><a class="button button-primary button-sm" href="<?= url('reports/print?'.http_build_query(array_merge(['type'=>'attendance','format'=>'pdf','from'=>$from,'to'=>$to],array_filter($filters)))) ?>"><i class="fa-solid fa-file-pdf"></i> Attendance PDF</a></div></form></section><div class="dashboard-grid charts-row"><section class="panel chart-panel"><div class="panel-head"><div><h2>Lead funnel</h2><p>Stage distribution</p></div></div><div class="chart-wrap"><canvas id="reportLeads"></canvas></div></section><section class="panel chart-panel"><div class="panel-head"><div><h2>Project status</h2><p>Portfolio mix</p></div></div><div class="chart-wrap"><canvas id="reportProjects"></canvas></div></section><section class="panel chart-panel span-2"><div class="panel-head"><div><h2>Revenue and collections</h2><p><?= e(date('d M Y',strtotime($from))) ?> to <?= e(date('d M Y',strtotime($to))) ?></p></div></div><div class="chart-wrap"><canvas id="reportFinance"></canvas></div></section></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Lead sources</h2><p>Volume and wins</p></div></div><div class="rank-list"><?php foreach($reports['sources'] as $source):?><div><span><?= e($source['label']) ?></span><strong><?= (int)$source['value'] ?> <small>(<?= (int)$source['won'] ?> won)</small></strong></div><?php endforeach;?></div></section><section class="panel span-2 table-panel"><div class="panel-head"><div><h2>Attendance detail</h2><p><?= count($reports['attendance']) ?> rows in selected range</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Staff</th><th>Status</th><th>Check-in</th><th>Check-out</th><th>Late</th><th>Worked</th></tr></thead><tbody><?php foreach(array_slice($reports['attendance'],0,50) as $row):?><tr><td><?= e(date('d M Y',strtotime($row['attendance_date']))) ?></td><td><?= e($row['name']) ?></td><td><span class="status-badge <?= status_class($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= $row['check_in_at']?e(date('g:i A',strtotime($row['check_in_at']))):'—' ?></td><td><?= $row['check_out_at']?e(date('g:i A',strtotime($row['check_out_at']))):'—' ?></td><td><?= (int)$row['late_minutes'] ?> min</td><td><?= floor($row['working_minutes']/60).'h '.($row['working_minutes']%60).'m' ?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<script>window.addEventListener('load',()=>{if(!window.Chart)return;Chart.defaults.font.family='Inter';const colors=['#0794B5','#101936','#F59E0B','#15803D','#DC2626','#8B5CF6','#64748B'];new Chart(document.getElementById('reportLeads'),{type:'doughnut',data:{labels:<?= json_encode(array_column($reports['lead_funnel'],'label')) ?>,datasets:[{data:<?= json_encode(array_map('intval',array_column($reports['lead_funnel'],'value'))) ?>,backgroundColor:colors}]},options:{responsive:true,maintainAspectRatio:false,cutout:'65%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true}}}}});new Chart(document.getElementById('reportProjects'),{type:'doughnut',data:{labels:<?= json_encode(array_column($reports['projects'],'label')) ?>,datasets:[{data:<?= json_encode(array_map('intval',array_column($reports['projects'],'value'))) ?>,backgroundColor:colors}]},options:{responsive:true,maintainAspectRatio:false,cutout:'65%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true}}}}});new Chart(document.getElementById('reportFinance'),{type:'bar',data:{labels:<?= json_encode(array_column($reports['finance'],'month')) ?>,datasets:[{label:'Invoiced',data:<?= json_encode(array_map('floatval',array_column($reports['finance'],'invoiced'))) ?>,backgroundColor:'#101936'},{label:'Received',data:<?= json_encode(array_map('floatval',array_column($reports['finance'],'received'))) ?>,backgroundColor:'#0794B5'}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true},x:{grid:{display:false}}}}});});</script>
